speed_tolerance"],"narrowings":[{"span":"s10","why":"'lawfully within the intersection' is read through the other road user's presence within the intersection; whether its presence there is lawful is not judged, so the subject yields to every such road user.","kind":"reading"}],"scenarios":[{"name":"forbid","expected":"violated","narrative":"Head s governing left-turn lane c displays circular_green with flashing_yellow_arrow(left); an oncoming car already inside i proceeds straight at 11 m/s; the car turns left across its path at 6 m/s, the closest approach of their centres 0.9 s ahead at 1.2 m."},{"name":"permit","expected":"compliant","narrative":"Same signal; no other road user is in the scene; the car turns left through i. The duty binds the subject alone and is met."},{"name":"idle","expected":"not_applicable","narrative":"s displays green_arrow(left) alone; the car turns left past an oncoming car."},{"name":"blind","expected":"unknown","narrative":"As forbid, but the source supplies no velocity-derived speed for the turning car: whether it moved on toward the oncoming car is unknown.","masked":["kin.speed"]}],"literals":[],"param_proposals":[{"name":"p.conflict_horizon","unit":"s","value":3.0,"convention":"time-to-collision threshold of the traffic-conflict technique: a closest approach later than this is not a present danger of a crash","source":"proposed this iteration by LVMC_11_12_070_B; repeated unchanged"},{"name":"p.conflict_centre_clearance","unit":"m","value":3.0,"convention":"centre-to-centre distance at the closest approach below which the bodies of a passenger car and another road user are taken to collide or nearly collide: about a car's half-length plus half a body width","source":"proposed this iteration by LVMC_11_12_070_B; repeated unchanged"},{"name":"p.halt_speed_tolerance","unit":"m/s","value":0.1,"convention":"the speed at or below which a sampled speed counts as no movement: the source's speed resolution","source":"proposed this iteration