nflict_centre_clearance","unit":"m","value":3.0,"convention":"centre-to-centre distance at the closest approach below which the bodies of a passenger car and another road user are taken to collide or nearly collide: about a car's half-length plus half a body width","source":"proposed this iteration by LVMC_11_12_070_B; repeated unchanged"},{"name":"p.halt_speed_tolerance","unit":"m/s","value":0.1,"convention":"the speed at or below which a sampled speed counts as no movement: the source's speed resolution","source":"proposed this iteration by LVMC_11_12_070_B; repeated unchanged"}],"gaps":[],"gap_resolutions":[]}
